  add column kind text not null default 'EXPENSE' check (kind in ('INCOME', 'EXPENSE', 'ASSET')),
  add column budget_group text check (budget_group in ('ESSENTIAL', 'VARIABLE', 'FINANCIAL')),
  add column active boolean not null default true;

