-- Movements already imported and classified automatically by a rule changed above follow the rule's new decision
-- (manual and client decisions are never touched). Recorded in the decision history.
with moved as (
  update cw_prod.transactions t set subcategory = r.subcategory, updated_at = now()
    from cw_prod.transaction_rules r
   where t.rule_id = r.id and r.scope = 'GLOBAL' and t.review_status = 'AUTO' and t.classification_source = 'GLOBAL_RULE'
     and t.nature = r.nature and t.subcategory is distinct from r.subcategory
  returning t.id, t.client_id, t.classification_source, t.rule_id, t.nature, t.subcategory, t.confidence, t.review_status)
insert into cw_prod.transaction_classifications (transaction_id, client_id, source, rule_id, nature, subcategory, confidence, review_status, decided_by)
select id, client_id, classification_source, rule_id, nature, subcategory, confidence, review_status, null from moved;

-- Unpaired "aplicação / resgate" movements auto-filed as transfers become investment contributions / redemptions.
with inv as (
  select t.id, case when t.direction = 'OUT' then 'EXPENSE' else 'ADJUSTMENT' end::cw_prod.txn_nature as nature,
         (select n.id from cw_prod.transaction_rules n where n.scope = 'GLOBAL' and n.pattern = r.pattern and n.direction = t.direction::text
           and n.subcategory = 'INVEST_CONTRIBUTION') as new_rule
    from cw_prod.transactions t join cw_prod.transaction_rules r on r.id = t.rule_id
   where r.scope = 'GLOBAL' and r.pattern in ('APLICACAO', 'APLIC AUTOMATICA', 'RESGATE') and r.nature = 'TRANSFER'
     and t.review_status = 'AUTO' and t.classification_source = 'GLOBAL_RULE' and t.nature = 'TRANSFER' and t.transfer_pair_id is null
     and ((r.pattern = 'RESGATE' and t.direction = 'IN') or (r.pattern <> 'RESGATE' and t.direction = 'OUT'))
), moved as (
  update cw_prod.transactions t set nature = inv.nature, subcategory = 'INVEST_CONTRIBUTION', rule_id = inv.new_rule, confidence = 'HIGH', updated_at = now()
    from inv where t.id = inv.id and inv.new_rule is not null
  returning t.id, t.client_id, t.classification_source, t.rule_id, t.nature, t.subcategory, t.confidence, t.review_status)
insert into cw_prod.transaction_classifications (transaction_id, client_id, source, rule_id, nature, subcategory, confidence, review_status, decided_by)
select id, client_id, classification_source, rule_id, nature, subcategory, confidence, review_status, null from moved;

-- ---------------------------------------------------------------- 2. consolidation (Engine A)
-- Same rules as before plus: INVESTMENT_SAVINGS (asset purchases, investments) is reported as "invested" and kept out
-- of spending, groups and categories (net of redemptions); income is also split by category.
create or replace function cw_prod.consolidation_month(p_client uuid, p_month date) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_from date := date_trunc('month', p_month)::date; v_to date; v jsonb; v_income numeric; v_gross numeric; v_adj numeric;
begin
  if not cw_prod_private.can_access_client(p_client) then perform cw_prod_private.deny(); end if;
  v_to := (v_from + interval '1 month')::date;
  with base as (
    select t.nature, t.direction, t.cash_effect, t.amount, t.review_status, t.competence_date, s.category_code,
           coalesce(s.planning_group, (select planning_group from cw_prod.transaction_subcategories where code = 'WORK_EXPENSES')) as grp
      from cw_prod.transactions t left join cw_prod.transaction_subcategories s on s.code = t.subcategory
     where t.client_id = p_client and t.competence_date >= v_from and t.competence_date < v_to
  ), counted as (
    select * from base where review_status in ('AUTO', 'CONFIRMED') and nature in ('INCOME', 'EXPENSE', 'ADJUSTMENT')
  ), signed as (
    select grp, category_code, case when nature = 'EXPENSE' then amount else -amount end as net, nature, amount
      from counted where nature in ('EXPENSE', 'ADJUSTMENT')
  ), spend as (
    select * from signed where grp is distinct from 'INVESTMENT_SAVINGS'
  ), invest as (
    select * from signed where grp = 'INVESTMENT_SAVINGS'
  )
  select jsonb_build_object(
    'income',      (select coalesce(sum(amount), 0) from counted where nature = 'INCOME'),
    'expense_gross', (select coalesce(sum(amount), 0) from spend where nature = 'EXPENSE'),
    'adjustments', (select coalesce(sum(amount), 0) from spend where nature = 'ADJUSTMENT'),
    'invested',    (select coalesce(sum(net), 0)::text from invest),
    'by_group',    coalesce((select jsonb_object_agg(grp, total) from (select grp::text, sum(net)::text as total from spend group by grp) g), '{}'),
    'by_category', coalesce((select jsonb_object_agg(category_code, total) from (select category_code, sum(net)::text as total from spend group by category_code) c), '{}'),
    'invested_by_category', coalesce((select jsonb_object_agg(category_code, total) from (select category_code, sum(net)::text as total from invest group by category_code) c), '{}'),
    'income_by_category', coalesce((select jsonb_object_agg(cat, total) from (select coalesce(category_code, 'INC_OTHER') as cat, sum(amount)::text as total
                                      from counted where nature = 'INCOME' group by 1) c), '{}'),
    'review',      jsonb_build_object('amount', (select coalesce(sum(amount), 0)::text from base where review_status = 'NEEDS_REVIEW'),
                                      'count', (select count(*) from base where review_status = 'NEEDS_REVIEW')),
    'cash',        jsonb_build_object('in',  (select coalesce(sum(amount), 0)::text from base where cash_effect = 'IN' and review_status <> 'IGNORED'),
                                      'out', (select coalesce(sum(amount), 0)::text from base where cash_effect = 'OUT' and review_status <> 'IGNORED')))
    into v;
  v_income := (v ->> 'income')::numeric; v_gross := (v ->> 'expense_gross')::numeric; v_adj := (v ->> 'adjustments')::numeric;
  return v || jsonb_build_object(
    'month', to_char(v_from, 'YYYY-MM'),
    'income', v_income::text, 'expense_gross', v_gross::text, 'adjustments', v_adj::text,
    'expense_net', (v_gross - v_adj)::text, 'savings', (v_income - v_gross + v_adj)::text,
    'savings_rate', case when v_income = 0 then null else round((v_income - v_gross + v_adj) / v_income, 6)::text end);
end $$;

-- ---------------------------------------------------------------- 3. deleting one imported file
-- Who asked for the deletion: only such files (not those queued by retention) can be removed from storage by their owner.
alter table cw_prod.documents add column deleted_by uuid, add column deleted_at timestamptz;
-- Removes the transactions read from the file (with their decision history and raw rows), the import records and the
-- file name; the original is queued and removed from storage right away by the app (or by the daily executor).
create function cw_prod.document_delete(p_document uuid) returns text
language plpgsql security definer set search_path = '' as $$
declare d cw_prod.documents; v_n integer;
begin
  select * into d from cw_prod.documents where id = p_document for update;
  if not found or d.client_id is null then perform cw_prod_private.deny(); end if;
  perform cw_prod_private.require_client(d.client_id);
  if d.status not in ('PENDING_UPLOAD', 'STORED') then perform cw_prod_private.deny(); end if;
  if exists (select 1 from cw_prod.clients where id = d.client_id and legal_hold) then
    raise exception 'legal hold' using errcode = '42501';
  end if;
  perform set_config('cw.privileged', 'on', true);
  delete from cw_prod.transaction_classifications c using cw_prod.transactions t where c.transaction_id = t.id and t.document_id = p_document;
  delete from cw_prod.transactions where document_id = p_document;
  get diagnostics v_n = row_count;
  delete from cw_prod.transaction_raw_data r using cw_prod.document_imports i where r.import_id = i.id and i.document_id = p_document;
  delete from cw_prod.transaction_installment_groups g
   where g.client_id = d.client_id and not exists (select 1 from cw_prod.transactions t where t.installment_group_id = g.id);
  delete from cw_prod.document_imports where document_id = p_document;
  update cw_prod.documents set status = 'PURGE_PENDING', original_filename = null, account_id = null, deleted_by = auth.uid(), deleted_at = now()
   where id = p_document;
  perform set_config('cw.privileged', '', true);
  perform cw_prod_private.write_audit('DELETE', 'documents', p_document::text, d.client_id, null,
    jsonb_build_object('purpose', d.purpose, 'transactions_removed', v_n));
  return d.storage_path;
end $$;

-- After the app removed the object: the deletion is complete (same check as the retention executor).
create function cw_prod.document_confirm_deleted(p_document uuid) returns boolean
language plpgsql security definer set search_path = '' as $$
declare d cw_prod.documents;
begin
  select * into d from cw_prod.documents where id = p_document for update;
  if not found or d.client_id is null then perform cw_prod_private.deny(); end if;
  if not cw_prod_private.can_access_client(d.client_id) then perform cw_prod_private.deny(); end if;
  if d.status <> 'PURGE_PENDING' or exists (select 1 from storage.objects o where o.bucket_id = 'cw-prod-documents' and o.name = d.storage_path) then
    return false;
  end if;
  update cw_prod.documents set status = 'PURGED', original_purged_at = now() where id = p_document;
  perform cw_prod_private.write_audit('PURGE', 'documents', p_document::text, d.client_id, null, jsonb_build_object('original_purged', true));
  return true;
end $$;

-- The owner may now remove the object of a file they deleted (no legal hold); files queued by retention stay with the
-- MASTER executor.
create or replace function cw_prod_private.storage_document_allowed(p_name text, p_op text) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((
    select case p_op
      when 'INSERT' then d.status = 'PENDING_UPLOAD' and d.uploaded_by = (select auth.uid()) and cw_prod_private.can_access_document(d.client_id, d.contact_id)
      when 'SELECT' then (d.status = 'STORED' and cw_prod_private.can_access_document(d.client_id, d.contact_id))
                         or (d.status = 'PURGE_PENDING' and (cw_prod_private.is_master() or (d.deleted_by is not null and cw_prod_private.can_access_document(d.client_id, d.contact_id)
                             and not exists (select 1 from cw_prod.clients c where c.id = d.client_id and c.legal_hold))))
      when 'DELETE' then d.status = 'PURGE_PENDING' and (cw_prod_private.is_master() or (d.deleted_by is not null and cw_prod_private.can_access_document(d.client_id, d.contact_id)
                             and not exists (select 1 from cw_prod.clients c where c.id = d.client_id and c.legal_hold)))
      else false end
    from cw_prod.documents d where d.storage_path = p_name), false)
$$;

revoke all on function cw_prod.document_delete(uuid), cw_prod.document_confirm_deleted(uuid) from public, anon;
grant execute on function cw_prod.document_delete(uuid), cw_prod.document_confirm_deleted(uuid) to authenticated;
commit;
